// Only search for models distinctive enough to give clean HN hits.
// A two-character name would match everything and poison the queue.
const models = $input.first().json.models ?? [];
return models
  .filter((m) => m.name && m.name.length >= 4)
  .slice(0, 40)
  .map((m) => ({ json: { slug: m.slug, name: m.name, provider: m.provider } }));

// Flatten every model's hits into one candidate list.
// $('One item per model').all()[i] keeps each response paired with the model
// it was searched for — the HTTP node replaces item data otherwise.
const sources = $('One item per model').all();
const decode = (s) =>
  String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#x2F;/g, '/')
    .replace(/&#x27;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();

const cutoff = Date.now() - 1000 * 60 * 60 * 24 * 30; // last 30 days only
const out = [];
const seen = new Set();

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const model = sources[i]?.json;
  if (!model) continue;
  for (const hit of items[i].json.hits ?? []) {
    const text = decode(hit.comment_text);
    // Too short to contain a usable account of actually using the thing.
    if (text.length < 180) continue;
    if (new Date(hit.created_at).getTime() < cutoff) continue;
    const url = `https://news.ycombinator.com/item?id=${hit.objectID}`;
    if (seen.has(url)) continue;
    seen.add(url);
    out.push({ json: { modelSlug: model.slug, modelName: model.name, sourceUrl: url, text: text.slice(0, 4000) } });
  }
}

// Cap per run so one busy window can't produce a giant Anthropic bill.
return out.slice(0, 12);

