// Pull the forced tool call out of each response and keep only the usable
// ones. Anything malformed is dropped rather than guessed at — a bad row
// here becomes a bad card in the review queue.
const candidates = $('Build candidates').all();
const reports = [];

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = candidates[i]?.json;
  if (!src) continue;

  const block = (items[i].json.content ?? []).find((b) => b.type === 'tool_use');
  const result = block?.input;
  if (!result || result.usable !== true) continue;

  const takeaway = String(result.takeaway ?? '').trim();
  if (takeaway.length < 10) continue;

  reports.push({
    modelSlug: src.modelSlug,
    taskCategory: result.taskCategory,
    takeaway: takeaway.slice(0, 400),
    sourceUrl: src.sourceUrl,
    sourceType: 'hn',
  });
}

// Nothing usable this run is a normal outcome, not an error.
if (!reports.length) return [];
return [{ json: { reports } }];
